pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 seed) public {
        amount = bound(amount, 1, 1e18);
        seed = bound(seed, amount, 1e30);

        Attacker attacker = new Attacker(c);

        // attacker deposits `amount`
        vm.deal(address(attacker), amount + seed);
        attacker.deposit(amount);

        // an unrelated party pads the contract balance so a buggy double
        // withdrawal would not underflow (wide domain: seed >= amount)
        address other = address(0xBEEF);
        vm.deal(other, seed);
        vm.prank(other);
        c.deposit{value: seed}();

        attacker.withdraw();

        // GENERAL RULE: one withdrawAll pays out exactly the credited amount,
        // even though the recipient re-enters during the external call.
        assertTrue(attacker.totalReceived() == amount);
    }
}

contract Attacker {
    C c;
    uint public totalReceived;
    bool reentered;

    constructor(C _c) { c = _c; }

    function deposit(uint256 amt) external payable {
        c.deposit{value: amt}();
    }

    function withdraw() external {
        c.withdrawAll();
    }

    receive() external payable {
        totalReceived += msg.value;
        if (!reentered) {
            reentered = true;
            c.withdrawAll();
        }
    }
}

